pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. Admissible domain: caller must not be the current owner (unauthorized)
        address initialOwner = c.owner();
        vm.assume(caller != initialOwner);
        vm.assume(newOwner != address(0)); // avoid burning ownership
        // 2. Drive the contract as the unauthorized caller
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // if the call succeeds, we check immutability
            assertTrue(c.owner() == initialOwner);
        } catch {
            // if the call reverts, owner must not change (trivially true)
            assertTrue(c.owner() == initialOwner);
        }
    }
}

