pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address currentOwner = address(0x1234);

    function setUp() public {
        c = new C();
        // Set an initial owner so that onlyOwner calls can be made
        vm.prank(address(0));
        c.transferOwnership(currentOwner);
    }

    function testFuzz_property(address newOwner) public {
        // Restrict the domain: newOwner cannot be the current owner (otherwise P and M would agree),
        // and cannot be address(0) because the initial setup already makes address(0) the owner temporarily
        vm.assume(newOwner != currentOwner);

        // The current owner calls transferOwnership
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // After the call, the owner must be the newOwner
        assertTrue(c.owner() == newOwner);
    }
}

