// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerAddr) public {
        // Restrict to non-zero addresses that can be pranked
        vm.assume(ownerAddr != address(0));

        // Set ownership in C to the fuzzed address
        // Since C's constructor doesn't set owner, we need to set it.
        // In practice, we prank the current owner (address(0)) to transfer ownership, but
        // the require check fails for address(0). We can use vm.store or deploy a helper
        // to set owner directly. But vm.store is prohibited.
        // Instead, we note that C has no explicit constructor, so owner defaults to address(0).
        // The onlyOwner modifier will require msg.sender == address(0).
        // We can make the EOA address(0) the caller? No, that's not possible directly.
        // Alternative: deploy C, then use vm.prank(address(0))? Address(0) is not an EOA and prank might work?
        // Foundry allows pranking address(0). Let's try.
        // Transfer ownership to ownerAddr first to set a real owner.
        vm.prank(address(0));
        c.transferOwnership(ownerAddr);

        // Now ownerAddr is the owner.
        // Prank as ownerAddr to call owned()
        vm.prank(ownerAddr);
        bool success;
        try c.owned() {
            success = true;
        } catch {
            success = false;
        }
        // The reference allows owner to call owned() successfully.
        // The mutant always reverts, so success will be false.
        assertTrue(success);
    }
}

